package com.clara.memory.semantic.api;public final class MemoryMatch {private final MemoryEntry entry;private final double score;public MemoryMatch(MemoryEntry entry,double score){if(entry==null||Double.isNaN(score)||score<-1.0||score>1.0) {throw new IllegalArgumentException(); }this.entry=entry;this.score=score;}public MemoryEntry getEntry(){return entry;}public double getScore(){return score;}}
